"""Reproducible image-first comparison; regions are not phonetic sign IDs."""
from pathlib import Path
import csv, hashlib, html, json, subprocess
R=Path(__file__).resolve().parents[1]
out=R/'round34_sources';out.mkdir(exist_ok=True)
specs=[('PTS1501_lower_context.jpg','PTS1501_photo.jpg',700,2160,1050,450),
       ('PTS1502_lower_context.jpg','PTS1502_photo.jpg',700,2200,1050,450),
       ('PTS1502_bottom_rows.jpg','PTS1502_photo.jpg',700,2070,1100,650),
       ('PTS1502_target_overlap.jpg','PTS1502_photo.jpg',700,1760,1100,610)]
for dest,src,x,y,w,h in specs:
 subprocess.run(['sips','-c',str(h),str(w),'--cropOffset',str(y),str(x),str(R/'round27_sources'/src),'--out',str(out/dest)],check=True,capture_output=True)
rows=[]
for dest,src,x,y,w,h in specs:
 rows.append(dict(file='round34_sources/'+dest,parent='round27_sources/'+src,x=x,y=y,width=w,height=h,parent_sha256=hashlib.sha256((R/'round27_sources'/src).read_bytes()).hexdigest(),sha256=hashlib.sha256((out/dest).read_bytes()).hexdigest()))
with (R/'data/round34_crops.csv').open('w',encoding='utf-8-sig',newline='') as f:
 wr=csv.DictWriter(f,fieldnames=list(rows[0]));wr.writeheader();wr.writerows(rows)
panels=[('PTS 1501','PTS1501_lower_context.jpg',1050,450,[(300,320,195,125),(485,315,145,120),(620,295,255,140)]),
        ('PTS 1502','PTS1502_bottom_rows.jpg',1100,650,[(150,315,295,135),(440,310,220,135),(655,290,275,160)])]
body=[]
for name,file,w,h,boxes in panels:
 overlays=''.join(f'<rect x="{x}" y="{y}" width="{bw}" height="{bh}"/><text x="{x+5}" y="{y+20}">R{i}</text>' for i,(x,y,bw,bh) in enumerate(boxes,1))
 body.append(f'<h2>{name}</h2><svg viewBox="0 0 {w} {h}" role="img" aria-label="Фотография с тремя областями сопоставления"><image href="round34_sources/{file}" width="{w}" height="{h}"/><g class="overlay">{overlays}</g></svg><p><a href="round34_sources/{file}">Открыть фрагмент без разметки</a></p>')
page='''<!doctype html><html lang="ru"><meta charset="utf-8"><title>Клинопись: сопоставление фотографий, блок 34</title><style>body{max-width:1100px;margin:30px auto;padding:0 18px;font:18px/1.5 system-ui;background:#f6f4ef;color:#222}svg{width:100%;background:#111}.overlay rect{fill:none;stroke:#00ffff;stroke-width:2}.overlay text{fill:#00ffff;font:bold 20px system-ui}body.hide .overlay{display:none}button{padding:12px;font-size:18px}h2{margin-bottom:8px}</style><h1>Повторяющаяся последовательность на двух конусах</h1><p>Блок 34 · 26 октября 2026. Сопоставляются видимые формы, без назначения звуков и перевода. R1–R3 — области сравнения, а не установленный алфавит и не окончательные границы знаков.</p><button onclick="document.body.classList.toggle('hide')">Показать / скрыть разметку</button>'''+''.join(body)+'''<h2>Результат сопоставления</h2><p>В одинаковом порядке повторяются: R1 — группа мелких косых вдавлений рядом с треугольной формой; R2 — перекрещивающиеся крупные клиновидные элементы; R3 — две крупные горизонтальные формы с правым вертикальным элементом. Различия ракурса, сохранности и исполнения не позволяют объявить все отдельные вдавления тождественными.</p><p>Подтверждена повторяемость графического фрагмента на двух физических предметах. Его произношение и значение этим сравнением не установлены. Номер строки и соответствие GI / ZI в этот результат не включены: полная привязка полос на закруглённой поверхности ещё не завершена.</p><p><a href="observations/2026-10-26_round34_photographic_sequence.txt">Подробный протокол</a> · <a href="data/round34_crops.csv">Координаты и контрольные суммы</a> · <a href="round27_sources/PTS1501_photo.jpg">Полная фотография PTS 1501</a> · <a href="round27_sources/PTS1502_photo.jpg">Полная фотография PTS 1502</a></p></html>'''
(R/'comparison_round34.html').write_text(page,encoding='utf-8')
report='''БЛОК 34. ГРАФИЧЕСКАЯ ПОСЛЕДОВАТЕЛЬНОСТЬ ПО ФОТОГРАФИЯМ
26 октября 2026

Задача: установить непосредственно наблюдаемую последовательность до назначения звуков. Происхождение письменности и родство языков в этом блоке не исследуются. Агглютинативность не принимается исходным условием.

Материал: фотографии двух физических конусов PTS 1501 / P201507 и PTS 1502 / P431422. Это ранее полученные источники, не новые находки. Происхождение фотографий зафиксировано в SOURCE_REGISTER.csv. Извлечены четыре фрагмента; координаты отсчитываются от левого верхнего угла полного снимка, единица — пиксель. Обработка: только прямоугольное кадрирование, без дорисовки и повышения резкости.

НАБЛЮДЕНИЕ
На фрагменте PTS1501_lower_context в нижней полосе и PTS1502_bottom_rows в средней полосе видна сходная последовательность трёх областей R1–R3. R1 содержит мелкие косые вдавления и соседнюю треугольную форму. R2 содержит перекрещивающиеся крупные клиновидные элементы. R3 содержит пару крупных горизонтальных форм с правым вертикальным элементом. Порядок областей совпадает. Это визуальное сопоставление двух предметов; оно не является автоматическим распознаванием или измеренным доказательством тождества каждого клина.

РЕЗУЛЬТАТ
Повторяемый графический фрагмент выделен без звукового именования. Нейтральная запись: R1 → R2 → R3. Здесь стрелка передаёт порядок слева направо на представленных изображениях, а не независимо установленное направление чтения. R1 может содержать несколько знаков. R2 и R3 также пока являются областями, а не доказанными единицами письменности. Число букв, слогов и слов из этой записи не выводится.

НЕЗАВЕРШЁННАЯ ПРОВЕРКА
Начальная задача блока — проверить опубликованное расхождение GI / ZI — пока не решена. На вращательных фотомонтажах пересекаются соседние ракурсы; кроме того, длинная редакционная строка в прорисовке может быть показана в несколько полос. Надёжной полной привязки выбранного фрагмента к редакционному номеру строки здесь нет. Поэтому мы не называем эти области ни GI, ни ZI, не утверждаем исправление прежнего чтения и не назначаем им казакские звуки. Редакторские чтения уже были известны исследователю; слепым этот опыт не является.

ЧТО ПОТРЕБУЕТСЯ ДЛЯ ЧТЕНИЯ
После полной графической привязки необходимо проверить кандидаты звуков по независимым ограничениям: древним параллельным написаниям имён, слоговым дублетам, двуязычным или учебным текстам, причём их фотографии также должны быть проверены. Сами повторения форм не определяют произношение: произвольная замена условных названий R1, R2, R3 другими названиями оставляет наблюдаемую картину неизменной. Поэтому сходство с современным словом будет гипотезой для проверки, а не способом назначить звук.

Отдельная задача после чтения — проверить морфологию по повторяемым элементам и их распределению. Ни агглютинация, ни происхождение извне не следуют из формы клиньев. В этом блоке новых фонетических значений: 0; новых переводов: 0. Книга не изменялась.

Просмотр: comparison_round34.html. В нём разметка отключается, сохранены ссылки на полные фотографии. Скрипт воспроизведения: scripts/prepare_round34.py.
'''
(R/'observations/2026-10-26_round34_photographic_sequence.txt').write_text(report,encoding='utf-8')
print(json.dumps(dict(crops=len(rows),physical_objects=2,comparison_regions=3,new_phonetic_values=0,new_translations=0),ensure_ascii=False))
